(function () {
  const openFromHash = () => {
    const match = location.hash.match(/^#producto=(.+)$/);
    if (!match) return;
    const code = decodeURIComponent(match[1]);
    const card = Array.from(document.querySelectorAll(".card[data-code]")).find((c) => c.dataset.code === code);
    if (!card) return;
    const section = card.closest(".acc-closed");
    if (section) section.querySelector(".acc-toggle")?.click();
    card.scrollIntoView({ behavior: "smooth", inline: "center", block: "nearest" });
    setTimeout(() => focusCard(card), 350);
    history.replaceState(null, "", location.pathname + location.search);
  };
  window.addEventListener("hashchange", openFromHash);
  window.addEventListener("load", openFromHash);
})();
